import{_ as t,c as a,o as p,ag as _,ai as i}from"./chunks/framework.DzmZFORK.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-05-08T12:00:00.000Z"},"headers":[],"relativePath":"diary/一切的固有经验都是枷锁.md","filePath":"diary/一切的固有经验都是枷锁.md"}'),n={name:"diary/一切的固有经验都是枷锁.md"};function o(r,e,s,l,c,d){return p(),a("div",null,e[0]||(e[0]=[_('<p>【封面图】 <img src="'+i+'" alt="324"></p><blockquote><p>今天晚上我回来煎了个牛排，非常的血腥，根本嚼不动，它就没熟透。我不知道是几分熟，可能是4分熟、5分熟。但是它确实很嫩了，煎牛排也是个技术活，不容易的，我已经煎了牛排可能以后一个月了，依旧是差强人意。</p></blockquote><p>【每天肯定自己的小进步】</p><ol><li>现在 git 可能已经不是在 AI Coding 时代最优解了。每天的 PR 和 commit 都已经流于形式，人类不知道这些正确的 diff 意图是什么？即便它带着很清晰的 message，你也不明白。以前出现了 BUG，可以通过 git 来看是谁改的，当初为什么改？现在还需要这个流程吗？</li><li>今天已经不打算再写这个文章，因为我回来确实太晚了。到家坐下坐椅子，折腾一下工作上的事情，一看就10点半了。然后我还得做牛排吃，十一点才能吃到晚饭。所以我其实时间非常短。但是我现在依旧在写这篇文档。这就是对自己坚持努力，我觉得，只要有一点时间，不要在意这个时间的跨度，我能做就做，尤其是这件事情，我想要坚持下来.</li><li>今天在座位上，我还没有等到我的手手表提醒我久坐的时候，我就已经起来到处闲逛了。也是 AI 给我带来一个非常好的一个便利的地方,相信自己之后会养成一个习惯，不需要通过手表的久坐提醒来让自己摆脱这样的情况。</li></ol><p>【今日份阅读启发】</p><p>今天看了很多书，我突然意识到一点，也看了很多文章。这些文章其实都有很多看的时候感觉有发人肺腑、警醒我心灵的那些内容。但是现在这个节点，这个晚上这个点，让我回想的时候，我感觉留在我脑子的东西并不多，我想不起来我看那些内容。</p><p>这可能才是我每天晚上需要回顾自己当天收获的一个重要原因。能够真正留到我心里面的，一定是我晚上这个节点所能想到的。</p><p>今天对我而言最印象深刻的，可能是玉博的采访那篇文章。他对于 UI 在当前 AI coding、AI 时代、Agent 时代的一个定位的原因的关系。他的观点，最重要的是 UI 不会消失，它会以另一种形式区别于传统的 UI 交互形式。举了一个例子，我觉得非常典型。</p><p>第一个给我们带来 UI 交互本身的交互，就是 ChatGPT 一开始通过对话的形式，把我们一个基本的需求给解决了，就是百度。</p><p>第二个节点，就是 ChatGPT。不对，我是说错了，是 DeepSeek。DeepSeek 首次把 think，就是它在背后运作的这些过程展示给用户。第一次让人使用的时候感觉非常的新。牛逼，感觉哇，它在背后做了好多东西，感觉这个大模型有魔法，会让你非常着迷。这其实本身它就是一种 UI。所以说这个时代，Agent 它 clean clear clean，它并没有也不会取代 UI，它取代的是一些我们传统的 UI，一些我们限于旧的知识以外的。</p><p>什么样的 UI 会被当前的 agent 所取代呢？有一些确定性的东西，它可能就不会被 UI 去取代。比如说我负责 setting 那一部分，这些都是非常确定性的东西，我要修改密码，我不可能再交给 agent 吧？它毕竟当前它还是一个概率性的一个模型，所以它没有办法实现一些肯定性的东西，而且我们一些所有 setting 里面的交互，包括修改密码，一些开关，它都是十几二十年了，你贸然去改变用户这样的习惯，有意义吗？没有意义。用户一定是需要通过 agent 来实现这样的操作吗？他不一定需要。所以还有很多 AI 是一定需要的。那么，AI 到底取代了什么样的一个 UI 交互呢？我们获取信息阅读的一些交互，我们浏览文章的一些交互，我们百度的一些交互，这些已经被替代了，还有其他的可能需要我更多的学习才能知道。</p>',11)]))}const m=t(n,[["render",o]]);export{g as __pageData,m as default};
